package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art.Art
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait RecoveryControl_coordination_recovery_control_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control)
  }

  /** helper function to set the values of all input ports.
   * @param recoveryEvent payload for data port recoveryEvent
   * @param faultSummary payload for data port faultSummary
   */
  def put_concrete_inputs(recoveryEvent : EIT_Image_Availability_Coordinator.RecoveryEvent.Type,
                          faultSummary : EIT_Image_Availability_Coordinator.FaultSummary): Unit = {
    put_recoveryEvent(recoveryEvent)
    put_faultSummary(faultSummary)
  }


  /** helper function to check RecoveryControl_coordination_recovery_control's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recoveryFrame method that will be called with the value of the outgoing data
   *        port 'recoveryFrame'.
   */
  def check_concrete_output(recoveryFrame: EIT_Image_Availability_Coordinator.RecoveryFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recoveryFrameValue: EIT_Image_Availability_Coordinator.RecoveryFrame = get_recoveryFrame().get
    if(!recoveryFrame(recoveryFrameValue)) {
      testFailures = testFailures :+ st"'recoveryFrame' did not match expected: value of the outgoing data port is ${recoveryFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recoveryEvent(value : EIT_Image_Availability_Coordinator.RecoveryEvent.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control.operational_api.recoveryEvent_Id, EIT_Image_Availability_Coordinator.RecoveryEvent_Payload(value))
  }

  // setter for in DataPort
  def put_faultSummary(value : EIT_Image_Availability_Coordinator.FaultSummary): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control.operational_api.faultSummary_Id, EIT_Image_Availability_Coordinator.FaultSummary_Payload(value))
  }

  // getter for out DataPort
  def get_recoveryFrame(): Option[EIT_Image_Availability_Coordinator.RecoveryFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.RecoveryFrame] = get_recoveryFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port recoveryFrame.  Expecting 'EIT_Image_Availability_Coordinator.RecoveryFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.RecoveryFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_recoveryFrame_payload(): Option[EIT_Image_Availability_Coordinator.RecoveryFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_recovery_control.initialization_api.recoveryFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.RecoveryFrame_Payload]]
  }

}
